window.AUTH=window.AUTH||{};window.AUTH["99-579"]={"d":"99-579","id":"1999/99-579","n":"Harris Trust & Savings Bank v. Salomon Smith Barney, Inc.","src":["osg"],"briefs":[{"k":"united-states","label":"Brief for the United States as amicus curiae supporting petitioners","date":"","url":"https://www.justice.gov/osg/media/226026/dl?inline","side":"pet","src":"osg","fmt":"PDF","detail":"https://www.justice.gov/osg/brief/harris-trust-savings-bank-v-salomon-brothers-amicus-merits","n":66}],"opinion":"https://tile.loc.gov/storage-services/service/ll/usrep/usrep530/usrep530238/usrep530238.pdf","tr":false,"items":[{"t":"case","label":"Administrative Comm. v. Gauf","cite":"188 F.3d 767","y":1999,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/188/767/","by":{"0":"12"}},{"t":"case","label":"Blue Cross & Blue Shield v. Sanders","cite":"138 F.3d 1347","y":1998,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/138/1347/","by":{"0":"12"}},{"t":"case","label":"Commissioner v. Keystone Consol. Indus., Inc.","cite":"508 U.S. 152","y":1993,"id":"1992/91-1677","sc":1,"op":5,"sum":"When applied to an employer's funding obligation, the contribution of unencumbered property to a defined benefit plan is a prohibited \"sale or exchange\" under §4975(c)(1)(A).","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"16, 17, 23"}},{"t":"case","label":"Firestone Tire & Rubber Co. v. Bruch","cite":"489 U.S. 101","y":1989,"id":"1988/87-1054","sc":1,"sum":"Petitioner Firestone Tire & Rubber Co. (Firestone) maintained, and was the plan administrator and fiduciary of, a termination pay plan and two other unfunded employee benefit plans governed by the Employee Retirement Income Security Act of 1974 (ERISA), 29 U. S. C. § 1001 et seq. After Firestone sold its Plastics Division to Occidental Petroleum Co. (Occidental), respondents, Plastics Division employees who were …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"22"}},{"t":"case","label":"Herman v. South Carolina Nat’l Bank","cite":"140 F.3d 1413","y":1998,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/140/1413/","op":1,"by":{"0":"2, 13"}},{"t":"case","label":"Landwehr v. DuPree","cite":"72 F.3d 726","y":1995,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/72/726/","op":1,"by":{"0":"14, 25, 26"}},{"t":"case","label":"Mertens v. Hewitt Assocs.","cite":"508 U.S. 248","y":1993,"id":"1992/91-1671","sc":1,"op":8,"sum":"ERISA does not authorize suits for money damages against nonfiduciaries who knowingly participate in a fiduciary's breach of fiduciary duty. ERISA §502(a)(3) permits plan participants to bring civil actions to obtain \"appropriate equitable relief\" to redress violations of the statute or a plan. Assuming, arguendo,that this creates a cause of action against nonfiduciaries who knowingly assist in a fiduciary's breach …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"passim"}},{"t":"case","label":"Nieto v. Ecker","cite":"845 F.2d 868","y":1988,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/845/868/","sum":"Holding that plaintiffs stated a cause of action under Section 502(a)(3) against a nonfiduciary party in interest that engaged in a prohibited transaction.","sumSrc":"brief:0","by":{"0":"29"}},{"t":"case","label":"Pilot Life Ins. Co. v. Dedeaux","cite":"481 U.S. 41","y":1987,"id":"1986/85-1043","sc":1,"sum":"ERISA pre-empts respondent's suit under state common law for alleged improper processing of his claim for benefits under the ERISAregulated benefit plan.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"22"}},{"t":"case","label":"Reich v. Compton","cite":"57 F.3d 270","y":1995,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/57/270/","op":1,"by":{"0":"2, 8"}},{"t":"case","label":"Reich v. Continental Cas. Co.","cite":"33 F.3d 754","y":1994,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/33/754/","by":{"0":"6, 24"}},{"t":"case","label":"Reich v. Rowe","cite":"20 F.3d 25","y":1994,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/20/25/","by":{"0":"8, 23, 28"}},{"t":"case","label":"Safe Deposit & Trust Co. v. Cahn","cite":"62 A. 819","y":1906,"court":"Md.","url":"https://www.courtlistener.com/c/A./62/819/","by":{"0":"23"}},{"t":"case","label":"Southern Council of Indus. Workers v. Ford","cite":"83 F.3d 966","y":1996,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/83/966/","by":{"0":"12"}},{"t":"case","label":"Stauffer v. Stauffer","cite":"351 A.2d 236","y":1976,"court":"Pa.","url":"https://www.courtlistener.com/c/A.2d/351/236/","by":{"0":"23"}},{"t":"case","label":"Strauss v. United States Fidelity & Guar. Co.","cite":"63 F.3d 174","y":1933,"url":"https://www.courtlistener.com/c/F.3d/63/174/","by":{"0":"23"}},{"t":"case","label":"Trafficante v. Metropolitan Life Ins. Co.","cite":"409 U.S. 205","y":1972,"id":"1972/71-708","sc":1,"sum":"The definition in § 810 (a) of \"person aggrieved,\" as \"any person who claims to have been injured by a discriminatory housing practice,\" shows a congressional intention to define standing as broadly as is permitted by Article III of the Constitution, and petitioners, being tenants of the apartment complex, have standing to sue under § 810 (a). Pp. 208-212. 446 F. 2d 1158, reversed and remanded.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"20, 21"}},{"t":"usc","label":"5 U.S.C. § 704","url":"https://www.law.cornell.edu/uscode/text/5/704","by":{"0":"17"}},{"t":"law","label":"Pub. L. No. 103-239","url":"https://www.govinfo.gov/link/statute/103/2123","by":{"0":"18"}},{"t":"usc","label":"29 U.S.C. § 1001","url":"https://www.law.cornell.edu/uscode/text/29/1001","subs":["(a)","(b)"],"by":{"0":"3, 9, 12, 13, 14, 15, 3, 9, 12, 13, 14, 15, 2, 10, 21, 2, 21"}},{"t":"usc","label":"29 U.S.C. § 1002","url":"https://www.law.cornell.edu/uscode/text/29/1002","subs":["(9)","(14)","(14)(B)","(21)","(21)(A)"],"stext":{"head":"§1002. Definitions","paras":[[0,"For purposes of this subchapter:"],[0,"(1) The terms \"employee welfare benefit plan\" and \"welfare plan\" mean any plan, fund, or program which was heretofore or is hereafter established or maintained by an employer or by an employee organization, or by both, to the extent that such plan, fund, or program was established or is maintained for the purpose of providing for its participants or their beneficiaries, through the purchase of insurance or otherwise, (A) medical, surgical, or hospital care or benefits, or benefits in the event of sickness, accident, disability, death or unemployment, or vacation benefits, apprenticeship or other training programs, or day care centers, scholarship funds, or prepaid legal services, or (B) any benefit described in section 186(c) of this title (other than pensions on retirement or death, and insurance to provide such pensions)."],[0,"(2)(A) Except as provided in subparagraph (B), the terms \"employee pension benefit plan\" and \"pension plan\" mean any plan, fund, or program which was heretofore or is hereafter established or maintained by an employer or by an employee organization, or by both, to the extent that by its express terms or as a result of surrounding circumstances such plan, fund, or program—"],[1,"(i) provides retirement income to employees, or"],[1,"(ii) results in a deferral of income by employees for periods extending to the termination of covered employment or beyond,"],[0,"regardless of the method of calculating the contributions made to the plan, the method of calculating the benefits under the plan or the method of distributing benefits from the plan. A distribution from a plan, fund, or program shall not be treated as made in a form other than retirement income or as a distribution prior to termination of covered employment solely because such distribution is made to an employee who has attained age 62 and who is not separated from employment at the time of such distribution."],[0,"(B) The Secretary may by regulation prescribe rules consistent with the standards and purposes of this chapter providing one or more exempt categories under which—"],[1,"(i) severance pay arrangements, and"],[1,"(ii) supplemental retirement income payments, under which the pension benefits of retirees or their beneficiaries are supplemented to take into account some portion or all of the increases in the cost of living (as determined by the Secretary of Labor) since retirement,"],[0,"shall, for purposes of this subchapter, be treated as welfare plans rather than pension plans. In the case of any arrangement or payment a principal effect of which is the evasion of the standards or purposes of this chapter applicable to pension plans, such arrangement or payment shall be treated as a pension plan. An applicable voluntary early retirement incentive plan (as defined in section 457(e)(11)(D)(ii) of title 26) making payments or supplements described in section 457(e)(11)(D)(i) of title 26, and an applicable employment retention plan (as defined in section 457(f)(4)(C) of title 26) making payments of benefits described in section 457(f)(4)(A) of title 26, shall, for purposes of this subchapter, be treated as a welfare plan (and not a pension plan) with respect to such payments and supplements."],[0,"(C) A pooled employer plan shall be treated as—"],[1,"(i) a single employee pension benefit plan or single pension plan; and"],[1,"(ii) a plan to which section 1060(a) of this title applies."],[0,"(3) The term \"employee benefit plan\" or \"plan\" means an employee welfare benefit plan or an employee pension benefit plan or a plan which is both an employee welfare benefit plan and an employee pension benefit plan."],[0,"(4) The term \"employee organization\" means any labor union or any organization of any kind, or any agency or employee representation committee, association, group, or plan, in which employees participate and which exists for the purpose, in whole or in part, of dealing with employers concerning an employee benefit plan, or other matters incidental to employment relationships; or any employees' beneficiary association organized for the purpose in whole or in part, of establishing such a plan."],[0,"(5) The term \"employer\" means any person acting directly as an employer, or indirectly in the interest of an employer, in relation to an employee benefit plan; and includes a group or association of employers acting for an employer in such capacity."],[0,"(6) The term \"employee\" means any individual employed by an employer."],[0,"(7) The term \"participant\" means any employee or former employee of an employer, or any member or former member of an employee organization, who is or may become eligible to receive a benefit of any type from an employee benefit plan which covers employees of such employer or members of such organization, or whose beneficiaries may be eligible to receive any such benefit."],[0,"(8) The term \"beneficiary\" means a person designated by a participant, or by the terms of an employee benefit plan, who is or may become entitled to a benefit thereunder."],[0,"(9) The term \"person\" means an individual, partnership, joint venture, corporation, mutual company, joint-stock company, trust, estate, unincorporated organization, association, or employee organization."],[0,"(10) The term \"State\" includes any State of the United States, the District of Columbia, Puerto Rico, the Virgin Islands, American Samoa, Guam, Wake Island, and the Canal Zone. The term \"United States\" when used in the geographic sense means the States and the Outer Continental Shelf lands defined in the Outer Continental Shelf Lands Act (43 U.S.C. 1331–1343)."],[0,"(11) The term \"commerce\" means trade, traffic, commerce, transportation, or communication between any State and any place outside thereof."],[0,"(12) The term \"industry or activity affecting commerce\" means any activity, business, or industry in commerce or in which a labor dispute would hinder or obstruct commerce or the free flow of commerce, and includes any activity or industry \"affecting commerce\" within the meaning of the Labor Management Relations Act, 1947 [29 U.S.C. 141 et seq.], or the Railway Labor Act [45 U.S.C. 151 et seq.]."],[0,"(13) The term \"Secretary\" means the Secretary of Labor."],[0,"(14) The term \"party in interest\" means, as to an employee benefit plan—"],[1,"(A) any fiduciary (including, but not limited to, any administrator, officer, trustee, or custodian), counsel, or employee of such employee benefit plan;"],[1,"(B) a person providing services to such plan;"],[1,"(C) an employer any of whose employees are covered by such plan;"],[1,"(D) an employee organization any of whose members are covered by such plan;"],[1,"(E) an owner, direct or indirect, of 50 percent or more of—"],[2,"(i) the combined voting power of all classes of stock entitled to vote or the total value of shares of all classes of stock of a corporation.1"],[2,"(ii) the capital interest or the profits interest of a partnership, or"],[2,"(iii) the beneficial interest of a trust or unincorporated enterprise,"],[1,"which is an employer or an employee organization described in subparagraph (C) or (D);"],[1,"(F) a relative (as defined in paragraph (15)) of any individual described in subparagraph (A), (B), (C), or (E);"],[1,"(G) a corporation, partnership, or trust or estate of which (or in which) 50 percent or more of—"],[2,"(i) the combined voting power of all classes of stock entitled to vote or the total value of shares of all classes of stock of such corporation,"],[2,"(ii) the capital interest or profits interest of such partnership, or"],[2,"(iii) the beneficial interest of such trust or estate,"],[1,"is owned directly or indirectly, or held by persons described in subparagraph (A), (B), (C), (D), or (E);"],[1,"(H) an employee, officer, director (or an individual having powers or responsibilities similar to those of officers or directors), or a 10 percent or more shareholder directly or indirectly, of a person described in subparagraph (B), (C), (D), (E), or (G), or of the employee benefit plan; or"],[1,"(I) a 10 percent or more (directly or indirectly in capital or profits) partner or joint venturer of a person described in subparagraph (B), (C), (D), (E), or (G)."],[0,"The Secretary, after consultation and coordination with the Secretary of the Treasury, may by regulation prescribe a percentage lower than 50 percent for subparagraph (E) and (G) and lower than 10 percent for subparagraph (H) or (I). The Secretary may prescribe regulations for determining the ownership (direct or indirect) of profits and beneficial interests, and the manner in which indirect stockholdings are taken into account. Any person who is a party in interest with respect to a plan to which a trust described in section 501(c)(22) of title 26 is permitted to make payments under section 1403 of this title shall be treated as a party in interest with respect to such trust."],[0,"(15) The term \"relative\" means a spouse, ancestor, lineal descendant, or spouse of a lineal descendant."],[0,"(16)(A) The term \"administrator\" means—"],[1,"(i) the person specifically so designated by the terms of the instrument under which the plan is operated;"],[1,"(ii) if an administrator is not so designated, the plan sponsor; or"],[1,"(iii) in the case of a plan for which an administrator is not designated and a plan sponsor cannot be identified, such other person as the Secretary may by regulation prescribe."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/1002?type=usc&year=mostrecent&link-type=html"},"op":4,"head":"§1002. Definitions","tname":"Labor","by":{"0":"20, 4, 16, 20, 20, 14"}},{"t":"usc","label":"29 U.S.C. § 1101","url":"https://www.law.cornell.edu/uscode/text/29/1101","by":{"0":"14"}},{"t":"usc","label":"29 U.S.C. § 1105","url":"https://www.law.cornell.edu/uscode/text/29/1105","subs":["(a)"],"stext":{"head":"§1105. Liability for breach of co-fiduciary","paras":[[0,"(a) Circumstances giving rise to liability"],[0,"In addition to any liability which he may have under any other provisions of this part, a fiduciary with respect to a plan shall be liable for a breach of fiduciary responsibility of another fiduciary with respect to the same plan in the following circumstances:"],[1,"(1) if he participates knowingly in, or knowingly undertakes to conceal, an act or omission of such other fiduciary, knowing such act or omission is a breach;"],[1,"(2) if, by his failure to comply with section 1104(a)(1) of this title in the administration of his specific responsibilities which give rise to his status as a fiduciary, he has enabled such other fiduciary to commit a breach; or"],[1,"(3) if he has knowledge of a breach by such other fiduciary, unless he makes reasonable efforts under the circumstances to remedy the breach."],[0,"(b) Assets held by two or more trustees"],[0,"(1) Except as otherwise provided in subsection (d) and in section 1103(a)(1) and (2) of this title, if the assets of a plan are held by two or more trustees—"],[1,"(A) each shall use reasonable care to prevent a co-trustee from committing a breach; and"],[1,"(B) they shall jointly manage and control the assets of the plan, except that nothing in this subparagraph (B) shall preclude any agreement, authorized by the trust instrument, allocating specific responsibilities, obligations, or duties among trustees, in which event a trustee to whom certain responsibilities, obligations, or duties have not been allocated shall not be liable by reason of this subparagraph (B) either individually or as a trustee for any loss resulting to the plan arising from the acts or omissions on the part of another trustee to whom such responsibilities, obligations, or duties have been allocated."],[0,"(2) Nothing in this subsection shall limit any liability that a fiduciary may have under subsection (a) or any other provision of this part."],[0,"(3)(A) In the case of a plan the assets of which are held in more than one trust, a trustee shall not be liable under paragraph (1) except with respect to an act or omission of a trustee of a trust of which he is a trustee."],[0,"(B) No trustee shall be liable under this subsection for following instructions referred to in section 1103(a)(1) of this title."],[0,"(c) Allocation of fiduciary responsibility; designated persons to carry out fiduciary responsibilities"],[0,"(1) The instrument under which a plan is maintained may expressly provide for procedures (A) for allocating fiduciary responsibilities (other than trustee responsibilities) among named fiduciaries, and (B) for named fiduciaries to designate persons other than named fiduciaries to carry out fiduciary responsibilities (other than trustee responsibilities) under the plan."],[0,"(2) If a plan expressly provides for a procedure described in paragraph (1), and pursuant to such procedure any fiduciary responsibility of a named fiduciary is allocated to any person, or a person is designated to carry out any such responsibility, then such named fiduciary shall not be liable for an act or omission of such person in carrying out such responsibility except to the extent that—"],[1,"(A) the named fiduciary violated section 1104(a)(1) of this title—"],[2,"(i) with respect to such allocation or designation,"],[2,"(ii) with respect to the establishment or implementation of the procedure under paragraph (1), or"],[2,"(iii) in continuing the allocation or designation; or"],[1,"(B) the named fiduciary would otherwise be liable in accordance with subsection (a)."],[0,"(3) For purposes of this subsection, the term \"trustee responsibility\" means any responsibility provided in the plan's trust instrument (if any) to manage or control the assets of the plan, other than a power under the trust instrument of a named fiduciary to appoint an investment manager in accordance with section 1102(c)(3) of this title."],[0,"(d) Investment managers"],[0,"(1) If an investment manager or managers have been appointed under section 1102(c)(3) of this title, then, notwithstanding subsections (a)(2) and (3) and subsection (b), no trustee shall be liable for the acts or omissions of such investment manager or managers, or be under an obligation to invest or otherwise manage any asset of the plan which is subject to the management of such investment manager."],[0,"(2) Nothing in this subsection shall relieve any trustee of any liability under this part for any act of such trustee."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/1105?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1105. Liability for breach of co-fiduciary","tname":"Labor","by":{"0":"19"}},{"t":"usc","label":"29 U.S.C. § 1106","url":"https://www.law.cornell.edu/uscode/text/29/1106","subs":["(a)"],"stext":{"head":"§1106. Prohibited transactions","paras":[[0,"(a) Transactions between plan and party in interest"],[0,"Except as provided in section 1108 of this title:"],[1,"(1) A fiduciary with respect to a plan shall not cause the plan to engage in a transaction, if he knows or should know that such transaction constitutes a direct or indirect—"],[2,"(A) sale or exchange, or leasing, of any property between the plan and a party in interest;"],[2,"(B) lending of money or other extension of credit between the plan and a party in interest;"],[2,"(C) furnishing of goods, services, or facilities between the plan and a party in interest;"],[2,"(D) transfer to, or use by or for the benefit of a party in interest, of any assets of the plan; or"],[2,"(E) acquisition, on behalf of the plan, of any employer security or employer real property in violation of section 1107(a) of this title."],[1,"(2) No fiduciary who has authority or discretion to control or manage the assets of a plan shall permit the plan to hold any employer security or employer real property if he knows or should know that holding such security or real property violates section 1107(a) of this title."],[0,"(b) Transactions between plan and fiduciary"],[0,"A fiduciary with respect to a plan shall not—"],[1,"(1) deal with the assets of the plan in his own interest or for his own account,"],[1,"(2) in his individual or in any other capacity act in any transaction involving the plan on behalf of a party (or represent a party) whose interests are adverse to the interests of the plan or the interests of its participants or beneficiaries, or"],[1,"(3) receive any consideration for his own personal account from any party dealing with such plan in connection with a transaction involving the assets of the plan."],[0,"(c) Transfer of real or personal property to plan by party in interest"],[0,"A transfer of real or personal property by a party in interest to a plan shall be treated as a sale or exchange if the property is subject to a mortgage or similar lien which the plan assumes or if it is subject to a mortgage or similar lien which a party-in-interest placed on the property within the 10-year period ending on the date of the transfer."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/1106?type=usc&year=mostrecent&link-type=html"},"op":6,"head":"§1106. Prohibited transactions","tname":"Labor","by":{"0":"1, 7, 9, 13, 14, 15, 18, 22, 26, 1, 7, 9, 13, 14, 15, 18, 22, 26"}},{"t":"usc","label":"29 U.S.C. § 1108","url":"https://www.law.cornell.edu/uscode/text/29/1108","stext":{"head":"§1108. Exemptions from prohibited transactions","paras":[[0,"(a) Grant of exemptions"],[0,"The Secretary shall establish an exemption procedure for purposes of this subsection. Pursuant to such procedure, he may grant a conditional or unconditional exemption of any fiduciary or transaction, or class of fiduciaries or transactions, from all or part of the restrictions imposed by sections 1106 and 1107(a) of this title. Action under this subsection may be taken only after consultation and coordination with the Secretary of the Treasury. An exemption granted under this section shall not relieve a fiduciary from any other applicable provision of this chapter. The Secretary may not grant an exemption under this subsection unless he finds that such exemption is—"],[1,"(1) administratively feasible,"],[1,"(2) in the interests of the plan and of its participants and beneficiaries, and"],[1,"(3) protective of the rights of participants and beneficiaries of such plan."],[0,"Before granting an exemption under this subsection from section 1106(a) or 1107(a) of this title, the Secretary shall publish notice in the Federal Register of the pendency of the exemption, shall require that adequate notice be given to interested persons, and shall afford interested persons opportunity to present views. The Secretary may not grant an exemption under this subsection from section 1106(b) of this title unless he affords an opportunity for a hearing and makes a determination on the record with respect to the findings required by paragraphs (1), (2), and (3) of this subsection."],[0,"(b) Enumeration of transactions exempted from section 1106 prohibitions"],[0,"The prohibitions provided in section 1106 of this title shall not apply to any of the following transactions:"],[1,"(1) Any loans made by the plan to parties in interest who are participants or beneficiaries of the plan if such loans (A) are available to all such participants and beneficiaries on a reasonably equivalent basis, (B) are not made available to highly compensated employees (within the meaning of section 414(q) of title 26) in an amount greater than the amount made available to other employees, (C) are made in accordance with specific provisions regarding such loans set forth in the plan, (D) bear a reasonable rate of interest, and (E) are adequately secured. A loan made by a plan shall not fail to meet the requirements of the preceding sentence by reason of a loan repayment suspension described under section 414(u)(4) of title 26."],[1,"(2)(A) Contracting or making reasonable arrangements with a party in interest for office space, or legal, accounting, or other services necessary for the establishment or operation of the plan, if no more than reasonable compensation is paid therefor."],[1,"(B)(i) No contract or arrangement for services between a covered plan and a covered service provider, and no extension or renewal of such a contract or arrangement, is reasonable within the meaning of this paragraph unless the requirements of this clause 1 are met."],[1,"(ii)(I) For purposes of this subparagraph:"],[2,"(aa) The term \"covered plan\" means a group health plan as defined section 2 1191b(a) of this title."],[2,"(bb) The term \"covered service provider\" means a service provider that enters into a contract or arrangement with the covered plan and reasonably expects $1,000 (or such amount as the Secretary may establish in regulations to account for inflation since December 27, 2020, as appropriate) or more in compensation, direct or indirect, to be received in connection with providing one or more of the following services, pursuant to the contract or arrangement, regardless of whether such services will be performed, or such compensation received, by the covered service provider, an affiliate, or a subcontractor:"],[3,"(AA) Brokerage services, for which the covered service provider, an affiliate, or a subcontractor reasonably expects to receive indirect compensation or direct compensation described in item (dd), provided to a covered plan with respect to selection of insurance products (including vision and dental), recordkeeping services, medical management vendor, benefits administration (including vision and dental), stop-loss insurance, pharmacy benefit management services, wellness services, transparency tools and vendors, group purchasing organization preferred vendor panels, disease management vendors and products, compliance services, employee assistance programs, or third party administration services."],[3,"(BB) Consulting, for which the covered service provider, an affiliate, or a subcontractor reasonably expects to receive indirect compensation or direct compensation described in item (dd), related to the development or implementation of plan design, insurance or insurance product selection (including vision and dental), recordkeeping, medical management, benefits administration selection (including vision and dental), stop-loss insurance, pharmacy benefit management services, wellness design and management services, transparency tools, group purchasing organization agreements and services, participation in and services from preferred vendor panels, disease management, compliance services, employee assistance programs, or third party administration services."],[2,"(cc) The term \"affiliate\", with respect to a covered service provider, means an entity that directly or indirectly (through one or more intermediaries) controls, is controlled by, or is under common control with, such provider, or is an officer, director, or employee of, or partner in, such provider."],[2,"(dd)(AA) The term \"compensation\" means anything of monetary value, but does not include non-monetary compensation valued at $250 (or such amount as the Secretary may establish in regulations to account for inflation since December 27, 2020, as appropriate) or less, in the aggregate, during the term of the contract or arrangement."],[2,"(BB) The term \"direct compensation\" means compensation received directly from a covered plan."],[2,"(CC) The term \"indirect compensation\" means compensation received from any source other than the covered plan, the plan sponsor, the covered service provider, or an affiliate. Compensation received from a subcontractor is indirect compensation, unless it is received in connection with services performed under a contract or arrangement with a subcontractor."],[2,"(ee) The term \"responsible plan fiduciary\" means a fiduciary with authority to cause the covered plan to enter into, or extend or renew, the contract or arrangement."],[2,"(ff) The term \"subcontractor\" means any person or entity (or an affiliate of such person or entity) that is not an affiliate of the covered service provider and that, pursuant to a contract or arrangement with the covered service provider or an affiliate, reasonably expects to receive $1,000 (or such amount as the Secretary may establish in regulations to account for inflation since December 27, 2020, as appropriate) or more in compensation for performing one or more services described in item (bb) under a contract or arrangement with the covered plan."],[1,"(II) For purposes of this subparagraph, a description of compensation or cost may be expressed as a monetary amount, formula, or a per capita charge for each enrollee or, if the compensation or cost cannot reasonably be expressed in such terms, by any other reasonable method, including a disclosure that additional compensation may be earned but may not be calculated at the time of contract if such a disclosure includes a description of the circumstances under which the additional compensation may be earned and a reasonable and good faith estimate if the covered service provider cannot otherwise readily describe compensation or cost and explains the methodology and assumptions used to prepare such estimate. Any such description shall contain sufficient information to permit evaluation of the reasonableness of the compensation or cost."],[1,"(III) No person or entity is a \"covered service provider\" within the meaning of subclause (I)(bb) solely on the basis of providing services as an affiliate or a subcontractor that is performing one or more of the services described in subitem (AA) or (BB) of such subclause under the contract or arrangement with the covered plan."],[1,"(iii) A covered service provider shall disclose to a responsible plan fiduciary, in writing, the following:"],[2,"(I) A description of the services to be provided to the covered plan pursuant to the contract or arrangement."],[2,"(II) If applicable, a statement that the covered service provider, an affiliate, or a subcontractor will provide, or reasonably expects to provide, services pursuant to the contract or arrangement directly to the covered plan as a fiduciary (within the meaning of section 1002(21) of this title)."],[2,"(III) A description of all direct compensation, either in the aggregate or by service, that the covered service provider, an affiliate, or a subcontractor reasonably expects to receive in connection with the services described in subclause (I)."],[2,"(IV)(aa) A description of all indirect compensation that the covered service provider, an affiliate, or a subcontractor reasonably expects to receive in connection with the services described in subclause (I)—"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/1108?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1108. Exemptions from prohibited transactions","tname":"Labor","by":{"0":"3, 12"}},{"t":"usc","label":"29 U.S.C. § 1109","url":"https://www.law.cornell.edu/uscode/text/29/1109","subs":["(a)"],"stext":{"head":"§1109. Liability for breach of fiduciary duty","paras":[[0,"(a) Any person who is a fiduciary with respect to a plan who breaches any of the responsibilities, obligations, or duties imposed upon fiduciaries by this subchapter shall be personally liable to make good to such plan any losses to the plan resulting from each such breach, and to restore to such plan any profits of such fiduciary which have been made through use of assets of the plan by the fiduciary, and shall be subject to such other equitable or remedial relief as the court may deem appropriate, including removal of such fiduciary. A fiduciary may also be removed for a violation of section 1111 of this title."],[0,"(b) No fiduciary shall be liable with respect to a breach of fiduciary duty under this subchapter if such breach was committed before he became a fiduciary or after he ceased to be a fiduciary."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/1109?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1109. Liability for breach of fiduciary duty","tname":"Labor","by":{"0":"13, 19, 14"}},{"t":"usc","label":"29 U.S.C. § 1111","url":"https://www.law.cornell.edu/uscode/text/29/1111","by":{"0":"14"}},{"t":"usc","label":"29 U.S.C. § 1112","url":"https://www.law.cornell.edu/uscode/text/29/1112","subs":["(a)","(c)"],"by":{"0":"14, 15, 15"}},{"t":"usc","label":"29 U.S.C. § 1132","url":"https://www.law.cornell.edu/uscode/text/29/1132","subs":["(a)","(a)(2)","(a)(3)","(a)(5)","(i)","(l)","(l)(1)","(l)(1)(A)","(l)(1)(B)","(l)(2)","(l)(3)(B)","(l)(4)"],"stext":{"head":"§1132. Civil enforcement","paras":[[0,"(a) Persons empowered to bring a civil action"],[0,"A civil action may be brought—"],[1,"(1) by a participant or beneficiary—"],[2,"(A) for the relief provided for in subsection (c) of this section, or"],[2,"(B) to recover benefits due to him under the terms of his plan, to enforce his rights under the terms of the plan, or to clarify his rights to future benefits under the terms of the plan;"],[1,"(2) by the Secretary, or by a participant, beneficiary or fiduciary for appropriate relief under section 1109 of this title;"],[1,"(3) by a participant, beneficiary, or fiduciary (A) to enjoin any act or practice which violates any provision of this subchapter or the terms of the plan, or (B) to obtain other appropriate equitable relief (i) to redress such violations or (ii) to enforce any provisions of this subchapter or the terms of the plan;"],[1,"(4) by the Secretary, or by a participant, or beneficiary for appropriate relief in the case of a violation of section 1025(c) or 1032(a) of this title;"],[1,"(5) except as otherwise provided in subsection (b), by the Secretary (A) to enjoin any act or practice which violates any provision of this subchapter, or (B) to obtain other appropriate equitable relief (i) to redress such violation or (ii) to enforce any provision of this subchapter;"],[1,"(6) by the Secretary to collect any civil penalty under paragraph (2), (4), (5), (6), (7), (8), or (9) of subsection (c) or under subsection (i) or (l);"],[1,"(7) by a State to enforce compliance with a qualified medical child support order (as defined in section 1169(a)(2)(A) of this title);"],[1,"(8) by the Secretary, or by an employer or other person referred to in section 1021(f)(1) of this title, (A) to enjoin any act or practice which violates subsection (f) of section 1021 of this title, or (B) to obtain appropriate equitable relief (i) to redress such violation or (ii) to enforce such subsection;"],[1,"(9) in the event that the purchase of an insurance contract or insurance annuity in connection with termination of an individual's status as a participant covered under a pension plan with respect to all or any portion of the participant's pension benefit under such plan constitutes a violation of part 4 of this title 1 or the terms of the plan, by the Secretary, by any individual who was a participant or beneficiary at the time of the alleged violation, or by a fiduciary, to obtain appropriate relief, including the posting of security if necessary, to assure receipt by the participant or beneficiary of the amounts provided or to be provided by such insurance contract or annuity, plus reasonable prejudgment interest on such amounts;"],[1,"(10) in the case of a multiemployer plan that has been certified by the actuary to be in endangered or critical status under section 1085 of this title, if the plan sponsor—"],[2,"(A) has not adopted a funding improvement or rehabilitation plan under that section by the deadline established in such section, or"],[2,"(B) fails to update or comply with the terms of the funding improvement or rehabilitation plan in accordance with the requirements of such section,"],[1,"by an employer that has an obligation to contribute with respect to the multiemployer plan or an employee organization that represents active participants in the multiemployer plan, for an order compelling the plan sponsor to adopt a funding improvement or rehabilitation plan or to update or comply with the terms of the funding improvement or rehabilitation plan in accordance with the requirements of such section and the funding improvement or rehabilitation plan; or"],[1,"(11) in the case of a multiemployer plan, by an employee representative, or any employer that has an obligation to contribute to the plan, (A) to enjoin any act or practice which violates subsection (k) of section 1021 of this title (or, in the case of an employer, subsection (l) of such section), or (B) to obtain appropriate equitable relief (i) to redress such violation or (ii) to enforce such subsection."],[0,"(b) Plans qualified under Internal Revenue Code; maintenance of actions involving delinquent contributions"],[0,"(1) In the case of a plan which is qualified under section 401(a), 403(a), or 405(a) 2 of title 26 (or with respect to which an application to so qualify has been filed and has not been finally determined) the Secretary may exercise his authority under subsection (a)(5) with respect to a violation of, or the enforcement of, parts 2 and 3 of this subtitle (relating to participation, vesting, and funding), only if—"],[1,"(A) requested by the Secretary of the Treasury, or"],[1,"(B) one or more participants, beneficiaries, or fiduciaries, of such plan request in writing (in such manner as the Secretary shall prescribe by regulation) that he exercise such authority on their behalf. In the case of such a request under this paragraph he may exercise such authority only if he determines that such violation affects, or such enforcement is necessary to protect, claims of participants or beneficiaries to benefits under the plan."],[0,"(2) The Secretary shall not initiate an action to enforce section 1145 of this title."],[0,"(3) Except as provided in subsections (c)(9) and (a)(6) (with respect to collecting civil penalties under subsection (c)(9)), the Secretary is not authorized to enforce under this part any requirement of part 7 against a health insurance issuer offering health insurance coverage in connection with a group health plan (as defined in section 1191b(a)(1) of this title). Nothing in this paragraph shall affect the authority of the Secretary to issue regulations to carry out such part."],[0,"(c) Administrator's refusal to supply requested information; penalty for failure to provide annual report in complete form"],[0,"(1) Any administrator (A) who fails to meet the requirements of paragraph (1) or (4) of section 1166 2 of this title, section 1021(e)(1) of this title, section 1021(f) of this title,,3 section 1025(a) of this title, or section 1032(a) of this title with respect to a participant or beneficiary, or (B) who fails or refuses to comply with a request for any information which such administrator is required by this subchapter to furnish to a participant or beneficiary (unless such failure or refusal results from matters reasonably beyond the control of the administrator) by mailing the material requested to the last known address of the requesting participant or beneficiary within 30 days after such request may in the court's discretion be personally liable to such participant or beneficiary in the amount of up to $100 a day from the date of such failure or refusal, and the court may in its discretion order such other relief as it deems proper. For purposes of this paragraph, each violation described in subparagraph (A) with respect to any single participant, and each violation described in subparagraph (B) with respect to any single participant or beneficiary, shall be treated as a separate violation."],[0,"(2) The Secretary may assess a civil penalty against any plan administrator of up to $1,000 a day from the date of such plan administrator's failure or refusal to file the annual report required to be filed with the Secretary under section 1021(b)(1) of this title. For purposes of this paragraph, an annual report that has been rejected under section 1024(a)(4) of this title for failure to provide material information shall not be treated as having been filed with the Secretary."],[0,"(3) Any employer maintaining a plan who fails to meet the notice requirement of section 1021(d) of this title with respect to any participant or beneficiary or who fails to meet the requirements of section 1021(e)(2) of this title with respect to any person or who fails to meet the requirements of section 1082(d)(12)(E) 2 of this title with respect to any person may in the court's discretion be liable to such participant or beneficiary or to such person in the amount of up to $100 a day from the date of such failure, and the court may in its discretion order such other relief as it deems proper."],[0,"(4) The Secretary may assess a civil penalty of not more than $1,000 a day for each violation by any person of subsection (j), (k), or (l) of section 1021 of this title or section 1144(e)(3) of this title."],[0,"(5) The Secretary may assess a civil penalty against any person of up to $1,000 a day from the date of the person's failure or refusal to file the information required to be filed by such person with the Secretary under regulations prescribed pursuant to section 1021(g) of this title."],[0,"(6) If, within 30 days of a request by the Secretary to a plan administrator for documents under section 1024(a)(6) of this title, the plan administrator fails to furnish the material requested to the Secretary, the Secretary may assess a civil penalty against the plan administrator of up to $100 a day from the date of such failure (but in no event in excess of $1,000 per request). No penalty shall be imposed under this paragraph for any failure resulting from matters reasonably beyond the control of the plan administrator."],[0,"(7) The Secretary may assess a civil penalty against a plan administrator of up to $100 a day from the date of the plan administrator's failure or refusal to provide notice to participants and beneficiaries in accordance with subsection (i) or (m) of section 1021 of this title. For purposes of this paragraph, each violation with respect to any single participant or beneficiary shall be treated as a separate violation."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/1132?type=usc&year=mostrecent&link-type=html"},"op":10,"head":"§1132. Civil enforcement","tname":"Labor","by":{"0":"passim, passim, passim, passim, passim, 18, 18, 18, 18, 18, 18, 21, 19"}},{"t":"usc","label":"29 U.S.C. § 1201","url":"https://www.law.cornell.edu/uscode/text/29/1201","by":{"0":"21"}},{"t":"usc","label":"29 U.S.C. § 1203","url":"https://www.law.cornell.edu/uscode/text/29/1203","subs":["(a)","(c)"],"by":{"0":"21, 21, 21"}},{"t":"usc","label":"26 U.S.C. § 4795","url":"https://www.law.cornell.edu/uscode/text/26/4795","by":{"0":"21"}},{"t":"usc","label":"26 U.S.C. § 4975","url":"https://www.law.cornell.edu/uscode/text/26/4975","subs":["(a)","(b)","(c)","(e)(1)","(e)(2)","(h)"],"stext":{"head":"§4975. Tax on prohibited transactions","paras":[[0,"(a) Initial taxes on disqualified person"],[0,"There is hereby imposed a tax on each prohibited transaction. The rate of tax shall be equal to 15 percent of the amount involved with respect to the prohibited transaction for each year (or part thereof) in the taxable period. The tax imposed by this subsection shall be paid by any disqualified person who participates in the prohibited transaction (other than a fiduciary acting only as such)."],[0,"(b) Additional taxes on disqualified person"],[0,"In any case in which an initial tax is imposed by subsection (a) on a prohibited transaction and the transaction is not corrected within the taxable period, there is hereby imposed a tax equal to 100 percent of the amount involved. The tax imposed by this subsection shall be paid by any disqualified person who participated in the prohibited transaction (other than a fiduciary acting only as such)."],[0,"(c) Prohibited transaction"],[0,"(1) General rule"],[1,"For purposes of this section, the term \"prohibited transaction\" means any direct or indirect—"],[2,"(A) sale or exchange, or leasing, of any property between a plan and a disqualified person;"],[2,"(B) lending of money or other extension of credit between a plan and a disqualified person;"],[2,"(C) furnishing of goods, services, or facilities between a plan and a disqualified person;"],[2,"(D) transfer to, or use by or for the benefit of, a disqualified person of the income or assets of a plan;"],[2,"(E) act by a disqualified person who is a fiduciary whereby he deals with the income or assets of a plan in his own interest or for his own account; or"],[2,"(F) receipt of any consideration for his own personal account by any disqualified person who is a fiduciary from any party dealing with the plan in connection with a transaction involving the income or assets of the plan."],[0,"(2) Special exemption"],[1,"The Secretary shall establish an exemption procedure for purposes of this subsection. Pursuant to such procedure, he may grant a conditional or unconditional exemption of any disqualified person or transaction, orders of disqualified persons or transactions, from all or part of the restrictions imposed by paragraph (1) of this subsection. Action under this subparagraph may be taken only after consultation and coordination with the Secretary of Labor. The Secretary may not grant an exemption under this paragraph unless he finds that such exemption is—"],[2,"(A) administratively feasible,"],[2,"(B) in the interests of the plan and of its participants and beneficiaries, and"],[2,"(C) protective of the rights of participants and beneficiaries of the plan."],[1,"Before granting an exemption under this paragraph, the Secretary shall require adequate notice to be given to interested persons and shall publish notice in the Federal Register of the pendency of such exemption and shall afford interested persons an opportunity to present views. No exemption may be granted under this paragraph with respect to a transaction described in subparagraph (E) or (F) of paragraph (1) unless the Secretary affords an opportunity for a hearing and makes a determination on the record with respect to the findings required under subparagraphs (A), (B), and (C) of this paragraph, except that in lieu of such hearing the Secretary may accept any record made by the Secretary of Labor with respect to an application for exemption under section 408(a) of title I of the Employee Retirement Income Security Act of 1974."],[0,"(3) Special rule for individual retirement accounts"],[1,"An individual for whose benefit an individual retirement account is established and his beneficiaries shall be exempt from the tax imposed by this section with respect to any transaction concerning such account (which would otherwise be taxable under this section) if, with respect to such transaction, the account ceases to be an individual retirement account by reason of the application of section 408(e)(2)(A) or if section 408(e)(4) applies to such account."],[0,"(4) Special rule for Archer MSAs"],[1,"An individual for whose benefit an Archer MSA (within the meaning of section 220(d)) is established shall be exempt from the tax imposed by this section with respect to any transaction concerning such account (which would otherwise be taxable under this section) if section 220(e)(2) applies to such transaction."],[0,"(5) Special rule for Coverdell education savings accounts"],[1,"An individual for whose benefit a Coverdell education savings account is established and any contributor to such account shall be exempt from the tax imposed by this section with respect to any transaction concerning such account (which would otherwise be taxable under this section) if section 530(d) applies with respect to such transaction."],[0,"(6) Special rule for health savings accounts"],[1,"An individual for whose benefit a health savings account (within the meaning of section 223(d)) is established shall be exempt from the tax imposed by this section with respect to any transaction concerning such account (which would otherwise be taxable under this section) if, with respect to such transaction, the account ceases to be a health savings account by reason of the application of section 223(e)(2) to such account."],[0,"(7) Special rule for provision of pharmacy benefit services"],[1,"Any party to an arrangement which satisfies the requirements of section 408(h) of the Employee Retirement Income Security Act of 1974 shall be exempt from the tax imposed by this section with respect to such arrangement."],[0,"(d) Exemptions"],[0,"Except as provided in subsection (f)(6), the prohibitions provided in subsection (c) shall not apply to—"],[1,"(1) any loan made by the plan to a disqualified person who is a participant or beneficiary of the plan if such loan—"],[2,"(A) is available to all such participants or beneficiaries on a reasonably equivalent basis,"],[2,"(B) is not made available to highly compensated employees (within the meaning of section 414(q)) in an amount greater than the amount made available to other employees,"],[2,"(C) is made in accordance with specific provisions regarding such loans set forth in the plan,"],[2,"(D) bears a reasonable rate of interest, and"],[2,"(E) is adequately secured;"],[1,"(2) any contract, or reasonable arrangement, made with a disqualified person for office space, or legal, accounting, or other services necessary for the establishment or operation of the plan, if no more than reasonable compensation is paid therefor;"],[1,"(3) any loan to a leveraged employee stock ownership plan (as defined in subsection (e)(7)), if—"],[2,"(A) such loan is primarily for the benefit of participants and beneficiaries of the plan, and"],[2,"(B) such loan is at a reasonable rate of interest, and any collateral which is given to a disqualified person by the plan consists only of qualifying employer securities (as defined in subsection (e)(8));"],[1,"(4) the investment of all or part of a plan's assets in deposits which bear a reasonable interest rate in a bank or similar financial institution supervised by the United States or a State, if such bank or other institution is a fiduciary of such plan and if—"],[2,"(A) the plan covers only employees of such bank or other institution and employees of affiliates of such bank or other institution, or"],[2,"(B) such investment is expressly authorized by a provision of the plan or by a fiduciary (other than such bank or institution or affiliates thereof) who is expressly empowered by the plan to so instruct the trustee with respect to such investment;"],[1,"(5) any contract for life insurance, health insurance, or annuities with one or more insurers which are qualified to do business in a State if the plan pays no more than adequate consideration, and if each such insurer or insurers is—"],[2,"(A) the employer maintaining the plan, or"],[2,"(B) a disqualified person which is wholly owned (directly or indirectly) by the employer establishing the plan, or by any person which is a disqualified person with respect to the plan, but only if the total premiums and annuity considerations written by such insurers for life insurance, health insurance, or annuities for all plans (and their employers) with respect to which such insurers are disqualified persons (not including premiums or annuity considerations written by the employer maintaining the plan) do not exceed 5 percent of the total premiums and annuity considerations written for all lines of insurance in that year by such insurers (not including premiums or annuity considerations written by the employer maintaining the plan);"],[1,"(6) the provision of any ancillary service by a bank or similar financial institution supervised by the United States or a State, if such service is provided at not more than reasonable compensation, if such bank or other institution is a fiduciary of such plan, and if—"],[2,"(A) such bank or similar financial institution has adopted adequate internal safeguards which assure that the provision of such ancillary service is consistent with sound banking and financial practice, as determined by Federal or State supervisory authority, and"],[2,"(B) the extent to which such ancillary service is provided is subject to specific guidelines issued by such bank or similar financial institution (as determined by the Secretary after consultation with Federal and State supervisory authority), and under such guidelines the bank or similar financial institution does not provide such ancillary service—"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/26/4975?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§4975. Tax on prohibited transactions","tname":"Internal Revenue Code","by":{"0":"29, 29, 29, 29, 29, 29, 29, 29"}},{"t":"usc","label":"28 U.S.C. § 1292","url":"https://www.law.cornell.edu/uscode/text/28/1292","subs":["(b)"],"stext":{"head":"§1292. Interlocutory decisions","paras":[[0,"(a) Except as provided in subsections (c) and (d) of this section, the courts of appeals shall have jurisdiction of appeals from:"],[1,"(1) Interlocutory orders of the district courts of the United States, the United States District Court for the District of the Canal Zone, the District Court of Guam, and the District Court of the Virgin Islands, or of the judges thereof, granting, continuing, modifying, refusing or dissolving injunctions, or refusing to dissolve or modify injunctions, except where a direct review may be had in the Supreme Court;"],[1,"(2) Interlocutory orders appointing receivers, or refusing orders to wind up receiverships or to take steps to accomplish the purposes thereof, such as directing sales or other disposals of property;"],[1,"(3) Interlocutory decrees of such district courts or the judges thereof determining the rights and liabilities of the parties to admiralty cases in which appeals from final decrees are allowed."],[0,"(b) When a district judge, in making in a civil action an order not otherwise appealable under this section, shall be of the opinion that such order involves a controlling question of law as to which there is substantial ground for difference of opinion and that an immediate appeal from the order may materially advance the ultimate termination of the litigation, he shall so state in writing in such order. The Court of Appeals which would have jurisdiction of an appeal of such action may thereupon, in its discretion, permit an appeal to be taken from such order, if application is made to it within ten days after the entry of the order: Provided, however, That application for an appeal hereunder shall not stay proceedings in the district court unless the district judge or the Court of Appeals or a judge thereof shall so order."],[0,"(c) The United States Court of Appeals for the Federal Circuit shall have exclusive jurisdiction—"],[1,"(1) of an appeal from an interlocutory order or decree described in subsection (a) or (b) of this section in any case over which the court would have jurisdiction of an appeal under section 1295 of this title; and"],[1,"(2) of an appeal from a judgment in a civil action for patent infringement which would otherwise be appealable to the United States Court of Appeals for the Federal Circuit and is final except for an accounting."],[0,"(d)(1) When the chief judge of the Court of International Trade issues an order under the provisions of section 256(b) of this title, or when any judge of the Court of International Trade, in issuing any other interlocutory order, includes in the order a statement that a controlling question of law is involved with respect to which there is a substantial ground for difference of opinion and that an immediate appeal from that order may materially advance the ultimate termination of the litigation, the United States Court of Appeals for the Federal Circuit may, in its discretion, permit an appeal to be taken from such order, if application is made to that Court within ten days after the entry of such order."],[0,"(2) When the chief judge of the United States Court of Federal Claims issues an order under section 798(b) of this title, or when any judge of the United States Court of Federal Claims, in issuing an interlocutory order, includes in the order a statement that a controlling question of law is involved with respect to which there is a substantial ground for difference of opinion and that an immediate appeal from that order may materially advance the ultimate termination of the litigation, the United States Court of Appeals for the Federal Circuit may, in its discretion, permit an appeal to be taken from such order, if application is made to that Court within ten days after the entry of such order."],[0,"(3) Neither the application for nor the granting of an appeal under this subsection shall stay proceedings in the Court of International Trade or in the Court of Federal Claims, as the case may be, unless a stay is ordered by a judge of the Court of International Trade or of the Court of Federal Claims or by the United States Court of Appeals for the Federal Circuit or a judge of that court."],[0,"(4)(A) The United States Court of Appeals for the Federal Circuit shall have exclusive jurisdiction of an appeal from an interlocutory order of a district court of the United States, the District Court of Guam, the District Court of the Virgin Islands, or the District Court for the Northern Mariana Islands, granting or denying, in whole or in part, a motion to transfer an action to the United States Court of Federal Claims under section 1631 of this title."],[0,"(B) When a motion to transfer an action to the Court of Federal Claims is filed in a district court, no further proceedings shall be taken in the district court until 60 days after the court has ruled upon the motion. If an appeal is taken from the district court's grant or denial of the motion, proceedings shall be further stayed until the appeal has been decided by the Court of Appeals for the Federal Circuit. The stay of proceedings in the district court shall not bar the granting of preliminary or injunctive relief, where appropriate and where expedition is reasonably necessary. However, during the period in which proceedings are stayed as provided in this subparagraph, no transfer to the Court of Federal Claims pursuant to the motion shall be carried out."],[0,"(e) The Supreme Court may prescribe rules, in accordance with section 2072 of this title, to provide for an appeal of an interlocutory decision to the courts of appeals that is not otherwise provided for under subsection (a), (b), (c), or (d)."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1292?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1292. Interlocutory decisions","tname":"Judiciary and Judicial Procedure","by":{"0":"29"}}]};